<?php
// Homepage stock is for tonight, in the hotel's timezone.
if (!defined('DONOTCACHEPAGE')) define('DONOTCACHEPAGE',true);
nocache_headers();
[$stock_in,$stock_out]=bch_form_dates();
$stock_days=bch_dates($stock_in,$stock_out);
get_header();
$acf_hero=absint(bch_home_field('image'));
$hero_url=$acf_hero?wp_get_attachment_image_url($acf_hero,'full'):(get_theme_mod('bch_hero_image')?:get_template_directory_uri().'/assets/retreat.svg');
$hero_alt=$acf_hero?(get_post_meta($acf_hero,'_wp_attachment_image_alt',true)?:'Không gian khách sạn Bảo Châu'):'Hình minh họa không gian nghỉ dưỡng';
?>
<main id="main">
<section class="hero"><img class="hero-image" src="<?php echo esc_url($hero_url); ?>" alt="<?php echo esc_attr($hero_alt); ?>"><div class="wrap hero-content"><p class="eyebrow"><?php echo esc_html(bch_home_field('eyebrow','BẢO CHÂU HOTEL · CHÀO ĐÓN BẠN')); ?></p><h1><?php echo nl2br(esc_html(str_replace('\\n',"\n",bch_home_field('title','Một chốn an yên.\nMột kỳ nghỉ trọn vẹn.')))); ?></h1><p><?php echo esc_html(bch_home_field('text','Gác lại nhịp sống vội vã, tận hưởng những ngày thảnh thơi trong không gian ấm áp của Bảo Châu.')); ?></p><div class="hero-links"><a class="button light" href="<?php echo esc_url(bch_home_field('cta_url')?:bch_page_url('phong-nghi')); ?>"><?php echo esc_html(bch_home_field('cta_label','Khám phá phòng nghỉ ↗')); ?></a><?php if (get_theme_mod('bch_demo',true)): ?><span class="demo-tag">HÌNH MINH HỌA · DEMO</span><?php endif; ?></div></div></section>
<div class="wrap search-shell"><?php echo bch_search_form(); ?></div>
<section class="section wrap intro" id="gioi-thieu"><div><p class="eyebrow"><?php echo esc_html(bch_home_field('intro_label','CHẠM VÀO SỰ THẢNH THƠI')); ?></p><h2><?php echo nl2br(esc_html(bch_home_field('intro_title','Nơi những điều giản dị làm nên kỳ nghỉ đẹp.'))); ?></h2></div><div class="intro-note"><p><?php echo esc_html(bch_home_field('intro','Một căn phòng dễ chịu, một giấc ngủ ngon và những khoảnh khắc dành riêng cho bạn. Bảo Châu chào đón mỗi chuyến đi bằng sự gần gũi và chu đáo.')); ?></p><a href="<?php echo esc_url(bch_page_url('gioi-thieu')); ?>">Làm quen với Bảo Châu →</a></div></section>
<section class="section wrap" id="phong"><div class="section-head"><div><p class="eyebrow"><?php echo esc_html(bch_home_field('rooms_label','KHÔNG GIAN CỦA RIÊNG BẠN')); ?></p><h2><?php echo esc_html(bch_home_field('rooms_title','Chọn một nơi để nghỉ ngơi.')); ?></h2></div><span><?php echo esc_html(bch_home_field('rooms_note','Ấm áp. Tinh tế. Vừa đủ.')); ?></span></div><p class="inventory-summary">Phòng trống cho đêm nay: <strong><?php echo esc_html(wp_date('d/m/Y',strtotime($stock_in.' 12:00:00'),new DateTimeZone('Asia/Ho_Chi_Minh')).' → '.wp_date('d/m/Y',strtotime($stock_out.' 12:00:00'),new DateTimeZone('Asia/Ho_Chi_Minh'))); ?></strong>. Chọn ngày khác ở ô tìm phòng để kiểm tra kỳ ở của bạn.</p><div class="room-grid">
<?php if (function_exists('bch_rooms')) foreach (bch_rooms() as $room):
    $stock_guests=min(2,(int)$room->capacity);
    $stock=bch_room_state($room,$stock_days,$stock_guests);
    $stock_link=add_query_arg(['room_detail'=>$room->id,'in'=>$stock_in,'out'=>$stock_out,'guests'=>$stock_guests],bch_page_url('phong-nghi'));
    if ($stock['upgrade']) $stock_link=bch_url(['room'=>$room->id,'in'=>$stock_in,'out'=>$stock_out,'guests'=>$stock_guests]);
?>
<article class="room-card"><a href="<?php echo esc_url($stock_link); ?>"><img loading="lazy" src="<?php echo esc_url(bch_theme_image($room)); ?>" alt="<?php echo esc_attr($room->name); ?><?php echo empty(json_decode($room->images,true))?' — hình minh họa':''; ?>"></a><p class="eyebrow">PHÒNG NGHỈ <?php if (get_theme_mod('bch_demo',true)) echo '· DEMO'; ?></p><h3><?php echo esc_html($room->name); ?></h3><p><?php if ((int)$room->area>0) echo esc_html($room->area).' m² &nbsp;·&nbsp;'; ?> <?php echo esc_html($room->capacity); ?> khách &nbsp;·&nbsp; <?php echo esc_html($room->bed); ?></p><?php bch_stock_badge($room,$stock); ?><p class="price"><small>Từ</small> <?php echo esc_html(bch_money($stock['quote']['total']??$room->price)); ?> <small>/ đêm</small></p><div class="card-actions"><?php if ($stock['left']>0 || $stock['upgrade']): ?><a class="button" href="<?php echo esc_url($stock_link); ?>"><?php echo $stock['upgrade']?'Xem phương án đổi phòng →':'Đặt phòng →'; ?></a><?php else: ?><button type="button" disabled><?php echo $stock['status']==='closed'?'Tạm ngừng bán':'Hết phòng'; ?></button><a href="<?php echo esc_url(bch_url()); ?>">Chọn ngày khác</a><?php endif; ?></div></article>
<?php endforeach; ?></div></section>
<section class="section services" id="tien-ich"><div class="wrap"><p class="eyebrow"><?php echo esc_html(bch_home_field('services_label','TẬN HƯỞNG TỪNG KHOẢNH KHẮC')); ?></p><h2><?php echo esc_html(bch_home_field('services_title','Những tiện nghi cho ngày thảnh thơi.')); ?></h2><div class="service-grid"><?php $i=0; foreach (explode("\n",bch_home_field('services',"Bữa sáng | Khởi đầu ngày mới thật nhẹ nhàng.\nKhông gian xanh | Một góc nhỏ để chậm lại.\nWi-Fi | Giữ kết nối trong suốt kỳ nghỉ.\nLễ tân | Đồng hành cùng từng chuyến đi.")) as $line): $item=explode('|',$line,2); ?><article class="service"><span>0<?php echo ++$i; ?></span><h3><?php echo esc_html(trim($item[0])); ?></h3><p><?php echo esc_html(trim($item[1]??'')); ?></p></article><?php endforeach; ?></div></div></section>
<section class="contact-section" id="lien-he">
<?php $contact_photo=absint(bch_home_field('contact_photo',get_theme_mod('bch_contact_photo'))); if ($contact_photo && wp_attachment_is_image($contact_photo)): ?>
<figure class="hotel-photo"><?php echo wp_get_attachment_image($contact_photo,'large',false,['class'=>'contact-photo','loading'=>'lazy','sizes'=>'(max-width: 680px) 100vw, 52vw']); ?><figcaption><?php echo esc_html(wp_get_attachment_caption($contact_photo)); ?></figcaption></figure>
<?php else: ?><img class="contact-art" loading="lazy" src="<?php echo esc_url(get_template_directory_uri().'/assets/retreat.svg'); ?>" alt="Hình minh họa khu vườn và hồ nước"><?php endif; ?>
<div class="contact-copy"><p class="eyebrow"><?php echo esc_html(bch_home_field('contact_label','HẸN GẶP BẠN TẠI BẢO CHÂU')); ?></p><h2><?php echo nl2br(esc_html(bch_home_field('contact_title','Kỳ nghỉ tiếp theo, bắt đầu từ đây.'))); ?></h2><p><?php echo nl2br(esc_html(bch_home_field('contact','Địa chỉ, điện thoại và email sẽ được khách sạn cập nhật trước khi mở đặt phòng.'))); ?></p><a class="button light" href="<?php echo esc_url(bch_theme_booking()); ?>"><?php echo esc_html(bch_home_field('contact_cta','Lên kế hoạch kỳ nghỉ ↗')); ?></a></div></section>
</main><?php get_footer(); ?>
